<script setup lang="ts">
import { ref } from 'vue';
import { api } from '../platform';
import { type Row } from '../../../shared/domain';
import { useWeather, weatherText, weatherSymbol, defaultCity, hometownCity, cityDetails, type WeatherPosition } from '../../../shared/weather';
const { city, weather, cities, search, error, searchError, loading, searching, locating, locationStatus, locationHint, current, days, load, find, locate: locateWeather } = useWeather(api);
const expanded = ref(false), choosing = ref(false);
function choose(row: Row) { choosing.value = false;load(row); }
async function locate(networkOnly = false) {
  const getPosition = () => new Promise<WeatherPosition>((resolve, reject) => uni.getLocation({ type: 'wgs84', isHighAccuracy: true, highAccuracyExpireTime: 10000, success: position => resolve(position), fail: reject }));
  if (await locateWeather(networkOnly ? undefined : getPosition)) choosing.value = false;
}
</script>
<template><view class="mobile-weather"><view class="weather-top"><view @click="choosing = !choosing"><text class="weather-place">⌖ {{ city.name }} ⌄</text><view class="weather-caption">出门前，看一眼天气</view></view><view v-if="weather" class="weather-summary" @click="expanded = !expanded"><text class="weather-degree">{{ Math.round(current.temperature_2m) }}°</text><view><text class="weather-icon">{{ weatherSymbol(current.weather_code, !!current.is_day) }}</text><text class="weather-state">{{ weatherText(current.weather_code) }}</text></view><text class="weather-expand">{{ expanded ? '⌃' : '⌄' }}</text></view><text v-else class="weather-caption">{{ loading ? '天气加载中…' : '暂未获取天气' }}</text></view><view v-if="weather" class="weather-caption">天气数据：Open-Meteo</view><view v-if="expanded && weather"><view class="weather-days"><view v-for="day in days" :key="day.date"><text>{{ day.label }}</text><text class="day-symbol">{{ weatherSymbol(day.code) }}</text><text>{{ Math.round(day.low) }}° / {{ Math.round(day.high) }}°</text></view></view><view class="weather-caption">体感 {{ current.apparent_temperature }}° · 湿度 {{ current.relative_humidity_2m }}% · 风速 {{ current.wind_speed_10m }} km/h</view><view class="weather-caption">{{ current.time?.replace('T', ' ') }} · 北京时间 · Open-Meteo</view></view><view v-if="locationHint" class="weather-caption">{{ locationHint }}</view><view v-if="error" class="weather-error">{{ error }}<button class="text-button" @click="load()">重新获取</button></view><view v-if="choosing" class="weather-picker"><view class="button-row"><button class="small" @click="choose(defaultCity)">苏州</button><button class="small" @click="choose(hometownCity)">沭阳</button><button class="small" :disabled="locating" @click="locate(false)">{{ locating ? '定位中…' : '使用我的位置' }}</button><button :disabled="locating" @click="locate(true)">网络定位</button></view><view class="safe-note">设备定位失败或误差较大时，尝试网络定位。网络估算会将公网IP交由ipwho.is查询，可能受VPN或运营商影响；仅用于天气，不写入会员资料。</view><view v-if="locationStatus" class="weather-caption">{{ locationStatus }}</view><view class="row"><input v-model="search" placeholder="城市、区县名或拼音" maxlength="40"/><button class="small" :disabled="searching" @click="find">搜索</button></view><view v-if="searchError" class="weather-error">{{ searchError }}</view><view v-for="row in cities" :key="row.id" class="weather-city" @click="choose(row)"><text>{{ row.name }}</text><view class="weather-caption">{{ cityDetails(row) }}</view></view></view></view></template>
<style scoped>
.mobile-weather{background:#eee5d2;border:1px solid #e3d8bf;border-radius:30rpx;padding:28rpx 30rpx;margin:28rpx 0;color:#685a40}.weather-top{display:flex;align-items:center;justify-content:space-between;gap:20rpx}.weather-place{font-size:28rpx;font-weight:600}.weather-caption{font-size:20rpx;color:#93846a;margin-top:8rpx;line-height:1.9}.weather-summary{display:flex;align-items:center;gap:18rpx}.weather-degree{font:80rpx/1 Georgia,serif;color:#354c56}.weather-icon{font-size:40rpx;color:#b38b48;display:block;line-height:1.2}.weather-state{font-size:20rpx;color:#8e7b56}.weather-expand{font-size:26rpx;color:#8f7e61}.weather-days{display:flex;padding:25rpx 0;margin:22rpx 0 12rpx;border-top:1px solid #d7ccb4}.weather-days>view{flex:1;text-align:center;font-size:22rpx}.weather-days text{display:block}.day-symbol{font-size:40rpx;margin:10rpx 0;color:#a68b58}.weather-error{font-size:22rpx;line-height:1.8;margin-top:15rpx}.weather-picker{margin-top:24rpx;border-top:1px solid #d7ccb4}.weather-picker button{background:#fffcf4;color:#7d6843}.weather-city{padding:22rpx 0;border-bottom:1px solid #dbd2bf;font-size:25rpx}.weather-picker .safe-note{color:#8f7e61}
.weather-picker .button-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12rpx;margin:24rpx 0}
.weather-picker .button-row button,.weather-picker .row button{display:flex;align-items:center;justify-content:center;min-height:88rpx;margin:0;padding:16rpx;font-size:24rpx;line-height:1.4;white-space:nowrap;width:100%}
.weather-picker .row{display:flex;align-items:center;gap:12rpx}
.weather-picker .row input{flex:1;min-width:0}
.weather-picker .row button{flex:0 0 104rpx;width:104rpx}
</style>
